function make(viewBox, d, fillRule) {
  return function FaIcon({ size = 14, style }) {
    return (
      <svg
        xmlns="http://www.w3.org/2000/svg"
        viewBox={viewBox}
        width={size}
        height={size}
        style={style}
        aria-hidden="true"
        fill="currentColor"
      >
        <path d={d} fillRule={fillRule} clipRule={fillRule} />
      </svg>
    );
  };
}

